// Time:  O(n^2)
// Space: O(1)

// dp
class Solution {
public:
    vector<int> findCoins(vector<int>& numWays) {
        vector<int> result;
        for (int i = 1; i <= size(numWays); ++i) {
            if (numWays[i - 1] == 1) {
                result.emplace_back(i);
                for (int j = size(numWays); j >= i; --j) {
                    numWays[j - 1] -= (j - i) - 1 >= 0 ? numWays[(j - i) - 1] : 1;
                }
            }
            if (numWays[i - 1]) {
                return {};
            }
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)
// dp
class Solution2 {
public:
    vector<int> findCoins(vector<int>& numWays) {
        vector<int> result;
        vector<int> dp(size(numWays) + 1);
        dp[0] = 1;
        for (int i = 1; i <= size(numWays); ++i) {
            if (numWays[i - 1] - dp[i] == 1) {
                result.emplace_back(i);
                for (int j = i; j <= size(numWays); ++j) {
                    dp[j] += dp[j - i];
                }
            }
            if (numWays[i - 1] - dp[i]) {
                return {};
            }
        }
        return result;
    }
};

kamyu-c-invert-binary-tree-0q77ymf:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

// Time:  O(n)
// Space: O(w), w is the max number of nodes of the levels.
// BFS solution.
class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (root != nullptr) {
            queue<TreeNode*> nodes;
            nodes.emplace(root);
            while (!nodes.empty()) {
                auto node = nodes.front();
                nodes.pop();
                swap(node->left, node->right);
                if (node->left != nullptr) {
                    nodes.emplace(node->left);
                }
                if (node->right != nullptr) {
                    nodes.emplace(node->right);
                }
            }
        }
        return root;
    }
};

// Time:  O(n)
// Space: O(h)
// Stack solution.
class Solution2 {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (root != nullptr) {
            stack<TreeNode*> nodes;
            nodes.emplace(root);
            while (!nodes.empty()) {
                auto node = nodes.top();
                nodes.pop();
                swap(node->left, node->right);
                if (node->left != nullptr) {
                    nodes.emplace(node->left);
                }
                if (node->right != nullptr) {
                    nodes.emplace(node->right);
                }
            }
        }
        return root;
    }
};

// Time:  O(n)
// Space: O(h) 
// DFS, Recursive solution.
class Solution3 {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (root != nullptr) {
            swap(root->left, root->right);
            invertTree(root->left);
            invertTree(root->right);
        }
        return root;
    }
};

kamyu-c-ip-to-cidr-0vrrf90:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<string> ipToCIDR(string ip, int range) {
        auto start = ipToInt(ip);
        vector<string> result;
        while (range > 0) {
            auto mask = max(33 - bitLength(start & ~(start - 1)),
                            33 - bitLength(range));
            result.emplace_back(intToIP(start) + "/" + to_string(mask));
            start += 1 << (32 - mask);
            range -= 1 << (32 - mask);
        }
        return result;
    }

private:
    uint32_t ipToInt(const string& ip) {
        uint32_t result = 0;
        for (const auto& n : split(ip, '.')) {
            result = 256 * result + stoi(n);
        }
        return result;
    }

    string intToIP(uint32_t n) {
        string ip;
        for (const auto& i : {24, 16, 8, 0}) {
            ip += to_string((n >> i) % 256);
            ip += ".";
        }
        ip.pop_back();
        return ip;
    }

    vector<string> split(const string& s, const char delim) {
        vector<string> tokens;
        stringstream ss(s);
        string token;
        while (getline(ss, token, delim)) {
            tokens.emplace_back(token);
        }
        return tokens;
    }

    uint32_t bitLength(uint32_t n) {
        uint32_t left = 1, right = 32;
        while (left <= right) {
            auto mid = left + (right - left) / 2;
            if ((1 << mid) > n) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

