// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool canReach(vector<int>& arr, int start) {
        queue<int> q({start});
        unordered_set<int> lookup = {start};
        while (!q.empty()) {
            const auto i = q.front(); q.pop();
            if (!arr[i]) {
                return true;
            }
            for (const auto& j : {i - arr[i], i + arr[i]}) {
                if (0 <= j && j < arr.size() && !lookup.count(j)) {
                    lookup.emplace(j);
                    q.emplace(j);
                }
            }
        }
        return false;
    }
};

kamyu-c-jump-game-iv-1997geh:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int minJumps(vector<int>& arr) {
        unordered_map<int, vector<int>> groups;
        for (int i = 0; i < arr.size(); ++i) {
            groups[arr[i]].emplace_back(i);
        }
        int result = 0;
        queue<pair<int, int>> q({{0, 0}});
        unordered_set<int> lookup = {0};
        while (!q.empty()) {
            const auto [pos, step] = q.front(); q.pop();
            if (pos == arr.size() - 1) {
                result = step;
                break;
            }
            unordered_set<int> neighbors(groups[arr[pos]].cbegin(),
                                         groups[arr[pos]].cend());
            groups[arr[pos]].clear();
            neighbors.emplace(pos - 1), neighbors.emplace(pos + 1);
            for (const auto& p : neighbors) {
                if (0 <= p && p < arr.size() && !lookup.count(p)) {
                    lookup.emplace(p);
                    q.emplace(p, step + 1);
                }
            }
        }
        return result;
    }
};

