kamyu-c-k-th-smallest-in-lexicographical:
// Time:  O(logn)
// Space: O(logn)

class Solution {
public:
    int findKthNumber(int n, int k) {
        int result = 0;

        vector<int> cnts(10);
        for (int i = 1; i <= 9; ++i) {
            cnts[i] = cnts[i - 1] * 10 + 1;
        }

        vector<int> nums;
        for (int i = n; i > 0; i /= 10) {
            nums.emplace_back(i % 10);
        }
        int total = n;
        int target = 0;
        for (int i = nums.size() - 1; i >= 0 && k; --i) {
            target = target * 10 + nums[i];
            const auto start = i == nums.size() - 1 ? 1 : 0;
            for (int j = start; j <= 9; ++j) {
                const auto candidate = result * 10 + j;
                int num;
                if (candidate < target) {
                    num = cnts[i + 1];
                } else if (candidate > target) {
                    num = cnts[i];
                } else {
                    num = total - cnts[i + 1] * (j - start) - cnts[i] * (9 - j);
                }
                if (k > num) {
                    k -= num;
                } else {
                    result = candidate;
                    --k;
                    total = num - 1;
                    break;
                }
            }
        }
        return result;
    }
};

// Time:  O(logn * logn)
// Space: O(logn)
class Solution2 {
public:
    int findKthNumber(int n, int k) {
        int result = 0;
        int index = 0;
        findKthNumberHelper(n, k, 0, &index, &result);
        return result;
    }

private:
    bool findKthNumberHelper(int n, int k, int cur, int *index, int *result) {
        if (cur) {
            ++(*index);
            if (*index == k) {
                *result = cur;
                return true;
            }
        }
        for (int i = (cur == 0 ? 1 : 0); i <= 9; ++i, cur /= 10) {
            cur = cur * 10 + i;
            int cnt = count(n, cur);
            if (k > cnt + *index) {
                *index += cnt;
                continue;
            }
            if (cur <= n && findKthNumberHelper(n, k, cur, index, result)) {
                return true;
            }
        }
        return false;
    }

    int count(int n, long long prefix) {  // Time:  O(logn)
        int result = 0;
        int number = 1;
        while (prefix <= n) {
            result += number;
            prefix *= 10;
            number *= 10;
        }
        result -= max(number / 10 - (n - prefix / 10 + 1), static_cast<long long>(0));
        return result;
    }
};

kamyu-c-k-th-smallest-prime-fraction-0io:
// Time:  O(nlogr)
// Space: O(1)

// Another cool O(n) solution by using quick select with median of median could be found here:
// https://leetcode.com/problems/k-th-smallest-prime-fraction/discuss/115545/O(n)

class Solution {
public:
    vector<int> kthSmallestPrimeFraction(vector<int>& A, int K) {
        vector<int> result;
        double left = 0.0, right = 1.0;
        while (right - left > 1e-8) {
            double mid = left + (right - left) / 2.0;
            if (check(mid, A, K, &result)) {
                right = mid;
            } else {
                left = mid;
            }
            if (!result.empty()) {
                break;
            }
        }
        return result;
    }

private:
    bool check(double mid, const vector<int>& A, int K, vector<int> *result) {
        vector<int> tmp(2);
        int count = 0;
        for (int i = 0, j = 0; i < A.size(); ++i) {
            for (; j < A.size(); ++j) {
                if (i < j && A[i] < A[j] * mid) {
                    if (tmp[0] == 0 || tmp[0] * A[j] < tmp[1] * A[i]) {
                        tmp[0] = A[i];
                        tmp[1] = A[j];
                    }
                    break;
                }
            }
            count += A.size() - j;
        }
        if (count == K) {
            *result = move(tmp);
        }
        return count >= K;
    }
};

kamyu-c-k-th-smallest-remaining-even-int:
// Time:  O(n + qlogn)
// Space: O(n)

// prefix sum, binary search
class Solution {
public:
    vector<int> kthRemainingInteger(vector<int>& nums, vector<vector<int>>& queries) {
        const auto& binary_search_right = [](int left, int right, const auto& check) {
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (!check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };

        vector<int> prefix(size(nums) + 1);
        for (int i = 0; i < size(nums); ++i) {
            prefix[i + 1] = prefix[i] + (nums[i] % 2 == 0 ? 1 : 0);
        }
        vector<int> result(size(queries));
        for (int i = 0; i < size(queries); ++i) {
            const auto& l = queries[i][0], &r = queries[i][1], &k = queries[i][2];
            const auto& j = binary_search_right(l, r, [&](int x) {
                return nums[x] / 2 < k + (prefix[x + 1] - prefix[l]);
            });
            result[i] = 2 * (k + (prefix[j + 1] - prefix[l]));
        }
        return result;
    }
};

