kamyu-c-largest-bst-subtree-1q65yzb:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int largestBSTSubtree(TreeNode* root) {
        if (!root) {
            return 0;
        }

        int max_size = 1;
        largestBSTSubtreeHelper(root, &max_size);
        return max_size;
    }

private:
    tuple<int, int, int> largestBSTSubtreeHelper(TreeNode* root, int *max_size) {
        if (!root->left && !root->right) {
            return make_tuple(1, root->val, root->val);
        }

        int left_size = 0, left_min = root->val, left_max = root->val;
        if (root->left) {
            tie(left_size, left_min, left_max) = largestBSTSubtreeHelper(root->left, max_size);
        }

        int right_size = 0, right_min = root->val, right_max = root->val;
        if (root->right) {
            tie(right_size, right_min, right_max) = largestBSTSubtreeHelper(root->right, max_size);
        }

        int size = 0;
        if ((!root->left || left_size > 0) && 
            (!root->right || right_size > 0) &&
            left_max <= root->val && root->val <= right_min) {
            size = 1 + left_size + right_size;
            *max_size = max(*max_size, size);
        }

        return make_tuple(size, left_min, right_max);
    }
};

kamyu-c-largest-color-value-in-a-directe:
// Time:  O(n + m)
// Space: O(n + m)

class Solution {
public:
    int largestPathValue(string colors, vector<vector<int>>& edges) {
        vector<vector<int>> adj(size(colors));
        vector<int> in_degree(size(colors));
        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1]);
            ++in_degree[edge[1]];
        }
        vector<int> q;
        for (int i = 0; i < size(colors); ++i) {
            if (!in_degree[i]) {
                q.emplace_back(i);
            }
        }
        vector<vector<int>> dp(size(colors), vector<int>(26));
        int result = -1, cnt = 0;
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                ++cnt;
                result = max(result, ++dp[u][colors[u] - 'a']);
                for (const auto& v : adj[u]) {
                    for (int c = 0; c < 26; ++c) {
                        dp[v][c] = max(dp[v][c], dp[u][c]);
                    }
                    if (!--in_degree[v]) {
                        new_q.emplace_back(v);
                    }
                }
            }
            q = move(new_q);
        }
        return cnt == size(colors) ? result : -1;
    }
};

