        unordered_set<int> dp = {0};
        for (const auto& stone : stones) {
            auto tmp(dp);
            for (const auto& i : dp) {
                tmp.emplace(i + stone);
            }
            dp = move(tmp);
        };
        const auto& S = accumulate(stones.cbegin(), stones.cend(), 0);
