kamyu-c-leaf-similar-trees-0kvc6gm:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    bool leafSimilar(TreeNode* root1, TreeNode* root2) {
        vector<TreeNode*> s1{root1} , s2{root2};
        while (!s1.empty() && !s2.empty()) {
            if (dfs(s1) != dfs(s2)) {
                return false;
            }
        }
        return s1.empty() && s2.empty();
    }

private:
    int dfs(vector<TreeNode*>& s) {
        while (true) {
            const auto node = s.back(); s.pop_back();
            if (node->right) {
                s.emplace_back(node->right);
            }
            if (node->left) {
                s.emplace_back(node->left);
            }
            if (!node->left && !node->right) {
                return node->val;
            }
        }
    }
};

kamyu-c-least-number-of-unique-integers-:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int findLeastNumOfUniqueInts(vector<int>& arr, int k) {
        const auto& count = counter(arr);
        const auto& count_count = counter(count);
        int result = count.size();
        for (int c = 1; c <= arr.size(); ++c) {
            if (!count_count.count(c)) {
                continue;
            }
            if (k < c * count_count.at(c)) {
                result -= k / c;
                break;
            }
            k -= c * count_count.at(c);
            result -= count_count.at(c);
        }
        return result;
    }

private:
    unordered_map<int, int> counter(const vector<int>& arr) {
        unordered_map<int, int> result;
        for (const auto& i : arr) {
            ++result[i];
        }
        return result;
    }

    unordered_map<int, int> counter(const unordered_map<int, int>& count) {
        unordered_map<int, int> result;
        for (const auto& [_, i] : count) {
            ++result[i];
        }
        return result;
    }
};

