// Time:  O(n)
// Space: O(1)

// greedy
class Solution {
public:
    string smallestBeautifulString(string s, int k) {
        const auto& check = [&](int i) {
            return (i - 1 < 0 || s[i - 1] != s[i]) && (i - 2 < 0 || s[i - 2] != s[i]);
        };

        int i = size(s) - 1;
        for (; i >= 0; --i) {
            for (++s[i]; !check(i); ++s[i]);
            if (s[i] - 'a' < k) {
                break;
            }
        }
        if (i < 0) {
            return "";
        }
        for (int j = i + 1; j < size(s); ++j) {
            s[j] = 'a';
            while (!check(j)) {
                ++s[j];
            }
        }
        return s;
    }
};

kamyu-c-lexicographically-smallest-equiv:
// Time:  O(nlog*n) ~= O(n), n is the length of S
// Space: O(n)

class Solution {
public:
    string smallestEquivalentString(string A, string B, string S) {
        UnionFind union_find(26);
        for (int i = 0; i < A.length(); ++i) {
            union_find.union_set(A[i] - 'a', B[i] - 'a');
        }
        string result;
        for (int i = 0; i < S.length(); ++i) {
            const auto& parent = union_find.find_set(S[i] - 'a');
            result.push_back(parent + 'a');
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        void union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root != y_root) {
                set_[max(x_root, y_root)] = min(x_root, y_root);
            }
        }

    private:
        vector<int> set_;
    };
};

kamyu-c-lexicographically-smallest-gener:
// Time:  O(n + m)
// Space: O(n + m)

// kmp, two pointers, sliding window, deque, greedy
class Solution {
public:
    string generateString(string str1, string str2) {
        const auto& getPrefix = [](const string& pattern) {
            vector<int> prefix(pattern.length(), -1);
            int j = -1;
            for (int i = 1; i < pattern.length(); ++i) {
                while (j > -1 && pattern[j + 1] != pattern[i]) {
                    j = prefix[j];
                }
                if (pattern[j + 1] == pattern[i]) {
                    ++j;
                }
                prefix[i] = j;
            }
            return prefix;
        };

        const int n = size(str1), m = size(str2);
        string candidate(n + m - 1, '*');
        auto prefix = getPrefix(str2);
        for (int i = 0, prev = -m; i < size(str1); ++i) {
            if (str1[i] != 'T') {
                continue;
            }
            const int diff = i - prev;
            if (diff < m) {
                if (prefix[m - 1] + 1 == m - diff) {
                    for (int j = 0; j < diff; ++j) {
                        candidate[(prev + m) + j] = str2[m - diff + j];
                    }
                } else {
                    return "";
                }
            } else {
                for (int j = 0; j < m; ++j) {
                    candidate[i + j] = str2[j];
                }
            }
            prev = i;
        }
