class Solution {
public:
    int longestCycle(vector<int>& edges) {
        int result = -1;
        vector<int> lookup(size(edges), -1);
        for (int i = 0, idx = 0; i < size(edges); ++i) {
            if (lookup[i] != -1) {
                continue;
            }
            const int start = idx;
            int j = i;
            for (; j != -1; j = edges[j]) {
                if (lookup[j] != -1) {
                    break;
                }
                lookup[j] = idx++;
            }
            if (j != -1 && lookup[j] >= start) {
                result = max(result, idx - lookup[j]);
            }
        }
        return result;
    }
};

kamyu-c-longest-duplicate-substring-0tlz:
// Time:  O(nlogn)
// Space: O(n)

// 1. other solution is to apply kasai's algorithm, refer to the link below:
// - https://leetcode.com/problems/longest-duplicate-substring/discuss/290852/Suffix-array-clear-solution
// 2. the best solution is to apply ukkonen's algorithm, refer to the link below:
// - https://leetcode.com/problems/longest-duplicate-substring/discuss/312999/best-java-on-complexity-and-on-space-solution-suffix-tree-67ms


class Solution {
public:
    string longestDupSubstring(string S) {
        auto left = 1ul, right = S.length() - 1;
        while (left <= right) {
            const auto mid = left + (right - left) / 2;
            if (!check(S, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return S.substr(check(S, right), right);
    }

private:
    uint64_t check(const string& S, uint64_t L) {
        static const uint64_t M = 1e9 + 7;
        static const uint64_t D = 26;
        uint64_t p = power(D, L, M);
        uint64_t curr = 0;
        for (uint64_t i = 0; i < L; ++i) {
            curr = ((D * curr) % M + S[i] - 'a') % M;
        }
        unordered_map<uint64_t, vector<uint64_t>> lookup;
        lookup[curr].emplace_back(L - 1);
        for (uint64_t i = L; i < S.length(); ++i) {
            curr = (D * curr) % M;
            curr = (curr + (S[i] - 'a')) % M;
            curr = (curr + (M - ((S[i - L] - 'a') * p) % M)) % M;
            if (lookup.count(curr)) {
                for (const auto& j : lookup[curr]) {  // check if string is the same when hash is the same
                    if (S.substr(j - L + 1, L) == S.substr(i - L + 1, L)) {
                        return i - L + 1;
                    }
                }
            }
            lookup[curr].emplace_back(i);
        }
        return 0;
    }

    uint64_t power(uint64_t D, uint64_t L, uint64_t M) {
        uint64_t result = 1;
        for (uint64_t i = 0; i < L; ++i) {
            result = (result * D) % M;
        }
        return result;
    }
};

