// Space: O(n)
// optimized from Solution5
class Solution4 {
public:
    int lengthOfLIS(vector<int>& nums) {
        set<int> sorted_nums(cbegin(nums), cend(nums));
        unordered_map<int, int> val_to_idx;
        for (const auto& x : sorted_nums) {
