        for (int i = size(s) - 1; i >= 0; --i) {
            for (int j = i + 1; j < size(s); ++j) {
                if (i == j - 1) {
                    if (s[j] == s[i]) {
                        dp[i % 2][j][s[j] - 'a'] = 2;
                    }
                } else {
                    for (int k = 0; k < 26; ++k) {
                        if(s[j] == s[i] && s[j] - 'a' != k) {
