        int q_d = depth(q);
        while (p_d > q_d) {
            p = p->parent;
            --p_d;
        }
        while (p_d < q_d) {
            q = q->parent;
            --q_d;
        }
        while (p != q) {
            p = p->parent;
            q = q->parent;
        }
        return p;
    }

