        for (int i = 0, j = 0; i < size(cnt); ++i) {
            for (int _ = 0; _ < cnt[i]; ++_) {
                result[j++] = 'a' + i;
            }
        }
        int left = size(s) / 2;
        int right = left + 1;
        for (; right < size(s) && result[right] == result[left]; ++right);
        for (; result[left] == result[(size(s) - 1) - left]; ++left, ++right) {
            swap(result[left], result[right]);
