        if (ranges::max(cnt) > size(s) / 2) {
            return "-1";
        }
        string result(size(s), 0);
        for (int i = 0; i < size(s) / 2; ++i) {
            int j = 0;
            for (; j < size(cnt); ++j) {
                if (cnt[j]) {
                    break;
                }
            }
            --cnt[j];
            result[i] = 'a' + j;
        }
        for (int i = size(s) / 2; i < size(s); ++i) {
            int j = 0;
            for (; j < size(cnt); ++j) {
                if (cnt[j] && result[(size(s) - 1) - i] != 'a' + j) {
                    break;
                }
            }
            --cnt[j];
            result[i] = 'a' + j;
        }
        return result;
    }
};

