class Solution {
public:
    int maxPossibleScore(vector<int>& start, int d) {
        const auto& binary_search_right = [](int left, int right, const auto& check) {
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (!check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };

        sort(begin(start), end(start));
        return binary_search_right(1, (start.back() + d) - start.front(), [&](int x) {
            int64_t curr = start[0];
            for (int i = 1; i < size(start); ++i) {
                curr = max(curr + x, static_cast<int64_t>(start[i]));
                if (curr > start[i] + d) {
                    return false;
                }
            }
            return true;
        });
    }
};

kamyu-c-maximize-spanning-tree-stability:
// Time:  O(n + eloge)
// Space: O(n)

// union find, kruskal's algorithm, mst, maximum spanning tree, greedy
class Solution {
public:
    int maxStability(int n, vector<vector<int>>& edges, int k) {
        UnionFind uf(n);
        int cnt = 0;
        int result = numeric_limits<int>::max();
        for (const auto& e : edges) {
            const auto& u = e[0], &v = e[1], &s = e[2], &m = e[3];
            if (!m) {
                continue;
            }
            if (!uf.union_set(u, v)) {
                return -1;
            }
            ++cnt;
            result = min(result, s);
        }
        sort(begin(edges), end(edges), [](const auto& a, const auto& b) {
            return a[2] > b[2];
        });
        for (const auto& e : edges) {
            const auto& u = e[0], &v = e[1], &s = e[2], &m = e[3];
            if (m) {
                continue;
            }
            if (!uf.union_set(u, v)) {
                continue;
            }
            ++cnt;
            if (cnt == (n - 1) - k) {
                result = min(result, s);
            } else if (cnt == n - 1) {
                result = min(result, 2 * s);
            }
        }
        return cnt == n - 1 ? result : -1;
    }

private:
class UnionFind {
    public:
        UnionFind(int n)
         : set_(n)
         , rank_(n) { 
            iota(begin(set_), end(set_), 0);
        }

        int find_set(int x) {
            vector<int> stk;
            while (set_[x] != x) {  // path compression
                stk.emplace_back(x);
                x = set_[x];
            }
            while (!empty(stk)) {
                const int y = stk.back(); stk.pop_back();
                set_[y] = x;
            }
            return x;
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            }
            set_[x] = y;  // Union by rank.
            if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            return true;
        }

    private:
        vector<int> set_;
        vector<int> rank_;
    };
};

kamyu-c-maximize-subarray-gcd-score-04k1:
// Time:  O(nlogn * logr), r = max(nums)
// Space: O(n + logr)

// number theory, suffix-gcd states, dp, binary search
class Solution {
public:
    long long maxGCDScore(vector<int>& nums, int k) {
        static const int INF = numeric_limits<int>::max();

        vector<int> lookup(size(nums));
        for (int i = 0; i < size(nums); ++i) {
            while ((nums[i] & 1) == 0) {
                nums[i] >>= 1;
                ++lookup[i];
            }
        }
        const int max_e = ranges::max(lookup);
        vector<vector<int>> lookup2(max_e + 1);
        for (int i = 0; i < size(lookup); ++i) {
            lookup2[lookup[i]].emplace_back(i);
        }
        int64_t result = 0;
        unordered_map<int, unordered_map<int, vector<int>>> dp;
        for (int i = 0; i < size(nums); ++i) {
            unordered_map<int, unordered_map<int, vector<int>>> new_dp;
            new_dp[nums[i]][lookup[i]] = {i, i};
            for (const auto& [g, e_v] : dp) {  // |g * e| = O(logr)
                for (const auto& [e, v] : e_v) {
                    const int ng = gcd(g, nums[i]);
                    const int ne = min(e, lookup[i]);
                    if (!new_dp.count(ng) || !new_dp[ng].count(ne)) {
                        new_dp[ng][ne] = {INF, INF};
                    }
                    new_dp[ng][ne][0] = min(new_dp[ng][ne][0], v[0]);
                    const int left = distance(cbegin(lookup2[ne]), lower_bound(cbegin(lookup2[ne]), cend(lookup2[ne]), v[0]));  // Time: O(logn)
                    const int right = distance(cbegin(lookup2[ne]), upper_bound(cbegin(lookup2[ne]), cend(lookup2[ne]), i)) - 1;  // Time: O(logn)
                    new_dp[ng][ne][1] = min(new_dp[ng][ne][1], (right - left + 1 <= k) ? v[0] : lookup2[ne][right - k] + 1);
                }
            }
            dp = move(new_dp);
            for (const auto& [g, e_v] : dp) {  // |g * e| = O(logr)
                for (const auto& [e, v] : e_v) {
                    result = max(result, (static_cast<int64_t>(g) * (i - v[0] + 1)) << e);
                    result = max(result, (static_cast<int64_t>(g) * (i - v[1] + 1)) << (e + 1));
                }
            }
        }
        return result;
    }
};

// Time:  O(n^2 + n * logr), r = max(nums)
// Space: O(1)
// number theory, brute force
class Solution2 {
public:
    long long maxGCDScore(vector<int>& nums, int k) {
        static const int INF = numeric_limits<int>::max();

        const auto& lower_bit = [](int x) {
            return x & -x;
        };

        int64_t result = 0;
        for (int i = 0; i < size(nums); ++i) {
            for (int j = i, g = 0, mn = INF, cnt = 0; j < size(nums); ++j) {
                g = gcd(g, nums[j]);
                const auto& bit = lower_bit(nums[j]);
                if (bit < mn) {
                    mn = bit;
                    cnt = 0;
                }
                if (bit == mn) {
                    ++cnt;
                }
                result = max(result, static_cast<int64_t>(g) * (j - i + 1) * (cnt <= k ? 2 : 1));
                if (static_cast<int64_t>(g) * (size(nums) - i) * 2 <= result) {
                    break;
                }
            }
        }
        return result;
    }
};

