// Time:  O(nlogn)
// Space: O(n)
// segment tree
class Solution_TLE {
public:
    long long maxSubarraySum(vector<int>& nums) {
        enum {MAX, TOTAL, PREFIX, SUFFIX};

        const auto& build = [&](int i) {
            return vector<int64_t>(4, nums[i]);
        };

        const auto& update = [](const auto& c) {
            return c;
        };

        const auto& query = [&](const auto& x, const auto& y) {
            if (empty(x)) {
                return y;
            }
            if (empty(y)) {
                return x;
            }
            return vector<int64_t>{
                max({x[MAX], y[MAX], x[SUFFIX] + y[PREFIX]}),
                x[TOTAL] + y[TOTAL],
                max(x[PREFIX], x[TOTAL] + y[PREFIX]),
                max(y[SUFFIX], x[SUFFIX] + y[TOTAL])
            };
        };

        const int mx = ranges::max(nums);
        if (mx < 0) {
            return mx;
        }
        const int mn = ranges::min(nums);
        if (mn >= 0) {
            return accumulate(cbegin(nums), cend(nums), 0ll);
        }
        unordered_map<int, vector<int>> groups;
        for (int i = 0; i < size(nums); ++i) {
            groups[nums[i]].emplace_back(i);
        }
        SegmentTree<vector<int64_t>> st(size(nums), build, update, query);
        int64_t result = st.tree[1][0];  // st.query(0, size(nums) - 1)[0]
        for (const auto& [k, v] : groups) {
            vector<int64_t> arr;
            for (const auto& i : v) {
                st.update(i, arr);
            }
            result = max(result, st.tree[1][0]);  // st.query(0, size(nums) - 1)[0]
            arr.assign(4, k);
            for (const auto& i : v) {
                st.update(i, arr);
            }
        }
        return result;
    }

private:
    // Template:
    // https://github.com/kamyu104/LeetCode-Solutions/blob/master/C++/booking-concert-tickets-in-groups.cpp
    template <typename T>
    class SegmentTree {
     public:
        explicit SegmentTree(
            int N,
            const function<T(const int&)>& build_fn,
            const function<T(const T&)>& update_fn,
            const function<T(const T&, const T&)>& query_fn)
          : tree(N > 1 ? 1 << (__lg(N - 1) + 2) : 2),
            base(N > 1 ? 1 << (__lg(N - 1) + 1) : 1),
            build_fn_(build_fn),
            query_fn_(query_fn),
            update_fn_(update_fn) {

            for (int i = base; i < base + N; ++i) {
                tree[i] = build_fn_(i - base);
            }
            for (int i = base - 1; i >= 1; --i) {
                tree[i] = query_fn_(tree[i << 1], tree[(i << 1) + 1]);
            }
        }

        void update(int i, const T& h) {
            int x = base + i;
            tree[x] = update_fn_(h);
            while (x > 1) {
                x >>= 1;
                tree[x] = query_fn_(tree[x << 1], tree[(x << 1) + 1]);
            }
        }

        T query(int L, int R) {
            L += base;
            R += base;
            T left, right;
            for (; L <= R; L >>= 1, R >>= 1) {
                if (L & 1) {
                    left = query_fn_(left, tree[L]);
                    ++L;
                }
                if ((R & 1) == 0) {
                    right = query_fn_(tree[R], right);
                    --R;
                }
            }
            return query_fn_(left, right);
        }

        vector<T> tree;
        int base;

    private:
        const function<T(const int&)> build_fn_;
        const function<T(const T&)> update_fn_;
        const function<T(const T&, const T&)> query_fn_;
    };
};

kamyu-c-maximize-subarrays-after-removin:
// Time:  O(n + m)
// Space: O(n + m)

// greedy
class Solution {
public:
    long long maxSubarrays(int n, vector<vector<int>>& conflictingPairs) {
        vector<vector<int64_t>> right(n);
        for (const auto& p : conflictingPairs) {
            int l = p[0] - 1, r = p[1] - 1;
            if (l > r) {
                swap(l, r);
            }
            right[r].emplace_back(l);
        }
        int64_t result = 0;
        vector<int64_t> top2(2, -1);
        vector<int64_t> cnt(n);
        for (int r = 0; r < n; ++r) {
            for (auto l : right[r]) {
                for (int i = 0; i < size(top2); ++i) {
                    if (l > top2[i]) {
                        swap(l, top2[i]);
                    }
                }
            }
            result += r - top2[0];
            if (top2[0] != -1) {
                cnt[top2[0]] += top2[0] - top2[1];
            }
        }
        return result + ranges::max(cnt);
    }
};

kamyu-c-maximize-sum-of-array-after-k-ne:
// Time:  O(n) ~ O(n^2), O(n) on average.
// Space: O(1)

// quick select solution
class Solution {
public:
    int largestSumAfterKNegations(vector<int>& A, int K) {
        nth_element(A.begin(), A.begin() + K, A.end());
        int remain = K;
        for (int i = 0; i < K; ++i) {
            if (A[i] < 0) {
                A[i] = -A[i];
                --remain;
            }
        }
        return accumulate(A.cbegin(), A.cend(), 0) -
               (remain % 2) * *min_element(A.cbegin(), A.cend()) * 2;
    }
};

// Time:  O(nlogn)
// Space: O(1)
class Solution2 {
public:
    int largestSumAfterKNegations(vector<int>& A, int K) {
        sort(A.begin(), A.end());
        int remain = K;
        for (int i = 0; i < K && A[i] < 0; ++i) {
            A[i] = -A[i];
            --remain;
        }
        return accumulate(A.cbegin(), A.cend(), 0) -
               (remain % 2) * *min_element(A.cbegin(), A.cend()) * 2;
    }
};

kamyu-c-maximize-sum-of-at-most-k-distin:
// Time:  O(nlogk)
// Space: O(k)

// heap, sort
class Solution {
public:
    vector<int> maxKDistinct(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> max_heap;
        for (const auto& x : unordered_set<int>(cbegin(nums), cend(nums))) {
            max_heap.emplace(x);
            if (size(max_heap) == k + 1) {
                max_heap.pop();
            }
        }
        vector<int> result;
        while (!empty(max_heap)) {
            result.emplace_back(max_heap.top());
            max_heap.pop();
        }
        ranges::reverse(result);
        return result;
    }
};

kamyu-c-maximize-sum-of-device-ratings-0:
// Time:  O(m * n)
// Space: O(1)

// greedy
class Solution {
public:
    long long maxRatings(vector<vector<int>>& units) {
        const auto& top2 = [](const auto& nums) {  // Time: O(k * n)
            int mn1 = numeric_limits<int>::max(), mn2 = numeric_limits<int>::max();
            for (auto x : nums) {
                if (x < mn1) {
                    mn2 = mn1;
                    mn1 = x;
                } else if (x < mn2) {
                    mn2 = x;
                }
            }
            return pair(mn1, mn2);
        };

        if (size(units[0]) == 1) {
            return accumulate(cbegin(units), cend(units), 0LL, [](const auto& accu, const auto& row) {
                return accu + row[0];
            });
        }
        int64_t total = 0;
        int mn1 = numeric_limits<int>::max(), mn2 = numeric_limits<int>::max();
        for (const auto& row : units) {
            const auto& [m1, m2] = top2(row);
            total += m2;
            mn1 = min(mn1, m1);
            mn2 = min(mn2, m2);
        }
        return total - mn2 + mn1;
    }
};

kamyu-c-maximize-sum-of-squares-of-digit:
// Time:  O(n)
// Space: O(1)

// greedy
class Solution {
public:
    string maxSumOfSquares(int num, int sum) {
        if (num * 9 < sum) {
            return "";
        }

        string result(num, '0');
        const int q = sum / 9;
        const int r = sum % 9;
        for (int i = 0; i < q; ++i) {
            result[i] = '9';
        }
        if (r) {
            result[q] = '0' + r;
        }
        return result;
    }
};

kamyu-c-maximize-sum-of-weights-after-ed:
// Time:  O(n)
// Space: O(n)

// iterative dfs, quick select
class Solution {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        vector<vector<pair<int, int>>> adj(size(edges) + 1);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2]);
            adj[e[1]].emplace_back(e[0], e[2]);
        }
        const auto& iter_dfs = [&]() {
            vector<pair<int64_t, int64_t>> cnt(size(adj));
            vector<tuple<int, int, int>> stk = {{1, 0, -1}};
            while (!empty(stk)) {
                const auto [step, u, p] = stk.back(); stk.pop_back();
                if (step == 1) {
                    stk.emplace_back(2, u, p);
                    for (const auto& [v, w] : adj[u]) {
                        if (v == p) {
                            continue;
                        }
                        stk.emplace_back(1, v, u);
                    }
                } else if (step == 2) {
                    int64_t curr = 0;
                    vector<int64_t> diff;
                    for (const auto& [v, w] : adj[u]) {
                        if (v == p) {
                            continue;
                        }
                        curr += cnt[v].first;
                        diff.emplace_back(max((cnt[v].second + w) - cnt[v].first, static_cast<int64_t>(0)));
                    }
                    if (k - 1 < size(diff)) {
                        nth_element(begin(diff), begin(diff) + (k - 1), end(diff), greater<int>());
                    }
                    cnt[u] = pair(accumulate(cbegin(diff), cbegin(diff) + min(k, static_cast<int>(size(diff))), curr),
                                  accumulate(cbegin(diff), cbegin(diff) + min(k - 1, static_cast<int>(size(diff))), curr));
                }
            }
            return cnt[0].first;
        };

        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(n)
// dfs, quick select
class Solution2 {
public:
    long long maximizeSumOfWeights(vector<vector<int>>& edges, int k) {
        vector<vector<pair<int, int>>> adj(size(edges) + 1);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2]);
            adj[e[1]].emplace_back(e[0], e[2]);
        }
        const function<pair<int64_t, int64_t>(int, int)> dfs = [&](int u, int p) {
            int64_t result = 0;
            vector<int64_t> diff;
            for (const auto& [v, w] : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& cnt = dfs(v, u);
                result += cnt.first;
                diff.emplace_back(max((cnt.second + w) - cnt.first, static_cast<int64_t>(0)));
            }
            if (k - 1 < size(diff)) {
                nth_element(begin(diff), begin(diff) + (k - 1), end(diff), greater<int>());
            }

            return pair(accumulate(cbegin(diff), cbegin(diff) + min(k, static_cast<int>(size(diff))), result),
                        accumulate(cbegin(diff), cbegin(diff) + min(k - 1, static_cast<int>(size(diff))), result));
        };

        return dfs(0, -1).first;
    }
};

kamyu-c-maximize-the-beauty-of-the-garde:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int maximumBeauty(vector<int>& flowers) {
        unordered_map<int, int> lookup;
        vector<int> prefix = {0};
        int result = numeric_limits<int>::min();
        for (int i = 0; i < size(flowers); ++i) {
            prefix.emplace_back(flowers[i] > 0 ? prefix.back() + flowers[i] : prefix.back());
            if (!lookup.count(flowers[i])) {
                lookup[flowers[i]] = i;
                continue;
            }
            result = max(result, (flowers[i] < 0) ? 2 * flowers[i] + prefix[i + 1] - prefix[lookup[flowers[i]]] : prefix[i + 1] - prefix[lookup[flowers[i]]]);
        }
        return result;
    }
};

kamyu-c-maximize-the-confusion-of-an-exa:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int maxConsecutiveAnswers(string answerKey, int k) {
        int result = 0, max_count = 0;
        unordered_map<char, int> count;
        for (int i = 0; i < size(answerKey); ++i) {
            ++count[answerKey[i]];
            max_count = max(max_count, count[answerKey[i]]);
            if (result - max_count >= k) {
                --count[answerKey[i - result]];
            } else {
                ++result;
            }
        }
        return result;
    }
};
